def svg(body,w=960,h=380):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img"><rect width="100%" height="100%" fill="#fff"/><g font-family="Arial,sans-serif" font-size="12" fill="#59636a">{body}</g></svg>'
def line(x,y,X,Y,c='#d6dad9',sw=1):return f'<path d="M{x},{y} L{X},{Y}" fill="none" stroke="{c}" stroke-width="{sw}"/>'
def txt(x,y,t,**kw):return f'<text x="{x}" y="{y}" '+ ' '.join(f'{k.replace("_","-")}="{v}"' for k,v in kw.items())+f'>{html.escape(str(t))}</text>'
