b+=line(75,280,900,280,'#8e999b')+line(75,35,75,280,'#8e999b')+line(75,82,900,82,'#ae7865')+txt(770,74,'target R² = 0.85')
pts=[]
for i,v in enumerate([.12,.32,.49,.61,.7,.77,.82,.86,.88,.89,.9,.91]):
 x=100+i*65;y=280-v*233;pts.append((x,y));b+=f'<circle cx="{x}" cy="{y}" r="{7 if i==7 else 4}" fill="{"#ae7865" if i==7 else "#368f9b"}"/>'+txt(x,305,i+1,text_anchor='middle')
