def table(head,rows,cls=''):
 return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{v}</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr '+('data-sample ' if cls=='samples' else '')+('class="removed"' if removed in str(row) else '')+'>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def story(s):return f'<div class="story"><p>{s}</p></div>'
def read(s):return f'<div class="reading">{s}</div>'
def build_report(lang):
 zh=lang=='zh';L=lambda a,b:a if zh else b;root=Path(lang)/'report';nav=L(['输入与背景','最终参数','过滤与样本质控','软阈值选择','网络与模块','模块与性状','模块深入与富集','Hub 基因','文件与复现'],['Inputs & backgrounds','Final parameters','Filtering & sample QC','Soft threshold','Network & modules','Module–trait','Detail & enrichment','Hub genes','Files & reproducibility'])
 title=L('从表达矩阵，<br>到共表达网络。','From expression<br>to connection.')
 out=f'''<aside class="rail"><a class="brand" href="../../index.html">rs<em>WGCNA</em><span style="font-size:10px;letter-spacing:0;margin-left:8px">REPORT</span></a><div class="eyebrow">{L('分析记录 / 2026','Analysis record / 2026')}</div><nav>'''+''.join(f'<a href="#step-{i}" class="{"active" if i==1 else ""}"><span>{i:02}</span>{n}</a>' for i,n in enumerate(nav,1))+f'''</nav><div class="rail-bottom">{L('设计预览 · 全部为模拟数据','Design preview · synthetic data')}<a href="{LAB}" target="_blank" rel="noopener">Xiao Wang Lab ↗</a><a href="../../DIRECTORY-STRUCTURE.md">{L('查看输出目录方案','Output directory specification')}</a></div></aside><main class="report"><div class="topline"><div class="eyebrow">{L("加权基因共表达网络分析", "Weighted gene co-expression network analysis")}</div><div class="actions"><a href="../../{'en' if zh else 'zh'}/report/index.html">{'English' if zh else '中文'}</a><button data-print>{L('打印 / 保存 PDF','Print / Save PDF')}</button></div></div><header class="hero"><div class="eyebrow">{L('拟南芥 · 干旱应答 · 示例项目','Arabidopsis · drought response · example project')}</div><h1>{title}</h1><p>{L('一份可追溯的分析记录。从输入文件、数据筛选到模块解析，逐步说明本次分析做了什么，以及每张图应该怎么看。','A traceable analysis record. Follow the inputs, filtering decisions and module analysis, with a practical guide to reading every figure.')}</p><div class="project-line">Arabidopsis_drought · 2026-10-27 14:30 +08:00 · rsWGCNA v0.5.0</div><div class="metrics">'''
 for n,t in [('18 → 17',L('输入 / 保留样本','Input / retained samples')),('8,000',L('进入网络的基因','Genes entering network')),('4',L('共表达模块（不含 grey）','Modules, excluding grey')),('30',L('展示的 Hub 候选','Displayed hub candidates'))]:out+=f'<div class="metric"><strong>{n}</strong><small>{t}</small></div>'
 out+=f'</div></header><div class="notice">{L("风格审阅样张：本页数字、图表、文件名和结果均为模拟示例，不代表对现有数据的分析。可下载的矩阵只含 8 行，用于检验下载体验。正式报告将替换为本次任务的真实结果。","Style review sample: all numbers, figures, filenames and results are synthetic examples, not an analysis of existing data. The downloadable matrix contains only 8 rows to demonstrate the download experience. Production reports will use actual job results.")}</div>'
 def step(i,desc):return f'<section class="step" id="step-{i}"><div class="step-head"><span class="step-no">{i:02}</span><h2>{nav[i-1]}</h2></div><p class="step-intro">{desc}</p>'
 def fig(name,folder,no,cap,guide):
  src=f'../result/{folder}/{name}.svg'
  return f'<figure><img src="{src}" alt="{html.escape(cap,quote=True)}"><figcaption><span><b>{L("图","Figure")} {no}.</b> {cap}</span><a href="{src}" download>{L("下载 SVG","Download SVG")} ↗</a></figcaption>{read(guide)}</figure>'
 out+=step(1,L('先记录分析从哪里开始。样本信息完整展示，并保留输入文件与注释背景的统计口径。','Start with the source data. All sample metadata are shown, along with the scope of annotation and background statistics.'))
 out+=table(L(['输入文件','文件名（示例）','内容'],['Input','Filename (example)','Contents']),[[L('表达矩阵','Expression matrix'),'counts.tsv',L('18 样本 × 24,000 基因；原始 read count','18 samples × 24,000 genes; raw read counts')],[L('样本信息','Sample metadata'),'sample_info.tsv',L('18 行；样本 ID、基因型、条件、重复','18 rows; sample ID, genotype, condition, replicate')],[L('性状来源','Trait source'),'sample_info.tsv → condition',L('本次选择的性状列','Selected trait column')],[L('基因注释','Gene annotation'),'annotation.tsv',L('24,000 个唯一基因；21,300 个具有描述','24,000 unique genes; 21,300 with descriptions')],['GO','gene2go.tsv',L('17,920 个唯一基因；4,260 个唯一 GO term；52,100 条去重映射','17,920 unique genes; 4,260 unique GO terms; 52,100 distinct mappings')],['KEGG','gene2kegg.tsv',L('5,842 个唯一基因；137 条通路；12,640 条去重映射','5,842 unique genes; 137 pathways; 12,640 distinct mappings')]])
 out+=f'<h3>{L("完整样本信息","Complete sample metadata")} <span class="tag">18 {L("行","rows")}</span></h3><input class="search" data-search aria-label="{L("搜索样本","Search samples")}" placeholder="{L("搜索样本 ID、条件或基因型…","Search by sample ID, condition or genotype…")}">'
 rows=[[n,g,c,r,L('已排除','Excluded') if n==removed else L('保留','Retained')] for n,g,c,r in samples]
 out+=table(L(['样本 ID','基因型','条件','重复','分析状态'],['Sample ID','Genotype','Condition','Replicate','Analysis status']),rows,'samples')
 out+=f'<div class="caption">{L("表 1 · 原始上传的 18 行均在此处；红色行表示后续手动排除的样本。样本 ID 与文件中的内容保持原样。","Table 1 · All 18 input rows are present. The highlighted row indicates a sample manually excluded later. IDs are preserved as uploaded.")} <a href="../result/01_input/sample_info.tsv" download>{L("下载样本表","Download metadata")}</a></div>'
 out+=read(L('背景文件的“唯一基因数”“唯一条目数”和“映射行数”分别统计。GO/KEGG 文件覆盖量不等于富集分析实际背景：正式报告还需列出所选背景与进入分析基因集的交集大小、未匹配 ID 和重复映射数。','Count unique genes, unique terms and mapping rows separately. File coverage is different from the effective enrichment universe: production reports must also list the intersection with the analyzed gene set, unmatched IDs and duplicate mappings.'))+'</section>'
 out+=step(2,L('这里记录实际运行成功的最终参数。正文解释分析决策，完整参数表用于复查与复现。','Record the final parameters used by successful runs. The narrative explains decisions; the complete parameter tables support reproducibility.'))
 labels={'filter':L('清洗过滤','Filtering'),'soft_threshold':L('软阈值搜索','Soft-threshold search'),'network':L('网络构建','Network construction'),'module_trait':L('模块与性状','Module–trait'),'module_detail':L('模块深入','Module detail'),'hub':L('Hub 筛选与网络','Hub selection & network')}
 for group,ps in params.items():
  rows=[[k,html.escape(json.dumps(v,ensure_ascii=False))] for k,v in ps.items()]
  out+=f'<details class="parameter" open><summary>{labels[group]}</summary>'+table(L(['参数','最终值'],['Parameter','Final value']),rows)+'</details>'
 out+=f'<div class="download-row"><a class="button" href="../result/00_provenance/parameters.final.json" download>{L("下载完整参数 JSON","Download all parameters")}</a><span class="muted">{L("示例参数；正式导出读取各步骤实际使用的参数，而非尚未运行的界面值。","Example parameters; production export reads parameters used by each run, rather than unexecuted edits in the UI.")}</span></div></section>'
 out+=step(3,L('明确区分样本删除、低表达过滤和高变基因选择，避免把所有减少都归因于“噪音”。','Separate sample exclusion, low-expression filtering and variable-gene selection. These are distinct decisions.'))
 out+=story(L('本例从 <strong>18 个样本 × 24,000 个基因</strong>开始。用户手动排除了 <strong>Mut_Drought_r3</strong>，剩余 17 个样本。本例选择保留原始 read count，不做数值转换。','The example starts with <strong>18 samples × 24,000 genes</strong>. The user manually excluded <strong>Mut_Drought_r3</strong>, leaving 17 samples. Raw read counts are used without transformation.'))
 out+=story(L('如果一个基因在<strong>超过 50% 的保留样本</strong>中 read count 小于 10，就因低表达被去除。对于本例的 17 个样本，这意味着<strong>至少 9 个样本</strong>低于 10 才会被过滤。这个步骤去掉 7,600 个基因，留下 16,400 个。','A gene is removed for low expression if its read count is below 10 in <strong>more than 50% of retained samples</strong>. With 17 samples, this means <strong>at least 9 samples</strong> below 10. This step removes 7,600 genes and leaves 16,400.'))
 out+=story(L('随后去掉样本间表达完全不变的 400 个基因，再按照<strong>中位数绝对离差（MAD）</strong>从大到小排序。MAD 描述一个基因在不同样本之间的表达波动；本例保留排名前 <strong>8,000</strong> 个基因进入后续网络分析，其余 8,000 个未入选。未入选不等于这些基因没有生物学意义。','Next, 400 genes with no variation across samples are removed. The remaining genes are ranked by <strong>median absolute deviation (MAD)</strong>, which describes how much expression varies between samples. The top <strong>8,000 genes</strong> enter network analysis; another 8,000 are not selected. Genes outside the top set may still be biologically meaningful.'))
 out+='<div class="flow">'+''.join(f'<div><small>{a}</small><b>{b}</b><small>{c}</small></div>{"<span>→</span>" if i<3 else ""}' for i,(a,b,c) in enumerate([(L('输入','Input'),'24,000',L('18 个样本','18 samples')),(L('去低表达后','After low-expression filter'),'16,400',L('17 个样本','17 samples')),(L('去零变异后','After constant-gene filter'),'16,000','MAD > 0'),(L('用于建网','Network input'),'8,000',L('MAD 排名前 8,000','Top 8,000 by MAD'))]))+'</div>'
 out+=table(L(['删除的样本','操作','原因'],['Excluded sample','Action','Reason']),[[removed,L('用户手动排除','Manually excluded'),L('未填写；不推测质量问题','Not provided; no inferred quality issue')]])
 out+=f'<div class="download-row"><a class="button primary" href="../result/02_filter/expression_filtered.preview.tsv" download>{L("下载矩阵示例 · 8 行","Download matrix sample · 8 rows")}</a><a href="../result/02_filter/removed_samples.tsv" download>{L("下载删除记录","Download exclusion log")}</a></div><p class="caption">{L("正式导出：result/02_filter/expression_filtered.tsv，保存完整的 8,000 基因 × 17 样本矩阵。本样张的 8 行文件仅演示链接，不冒充完整结果。","Production export: result/02_filter/expression_filtered.tsv, containing the complete 8,000-gene × 17-sample matrix. The 8-row preview demonstrates the link only.")}</p>'
 out+=fig('sample-tree','02_filter',1,L('样本聚类树 · 删除前视图；底部色带为 condition、genotype。','Sample dendrogram before exclusion; annotation rows: condition, genotype.'),L('怎么看：相邻分支表示表达模式更相似。色带从上到下严格使用用户选择的 condition、genotype；类别使用 app 默认调色板。红色标签标识手动排除项。此图为布局示意，不能据此判断真实离群样本。正式报告同时保留删除前和最终样本树，并复用 app 的叶序、色带、标签和颜色。','How to read: nearby branches indicate more similar expression profiles. Annotation rows follow the selected order: condition, genotype, using the app default category palette. The red label marks a manual exclusion. This layout illustration cannot identify actual outliers. Production reports retain both before-exclusion and final trees, reusing the app leaf order, annotation rows, labels and colors.'))+'</section>'
 out+=step(4,L('先观察候选值，再记录最终采用值及其选择依据。','Inspect candidate values, then record the chosen power and the reason for choosing it.'))
 out+=story(L('本例使用 signed 网络，选择 <strong>β = 8</strong>。示例拟合曲线在此首次达到 R² ≥ 0.85。软阈值会放大较强相关、减弱较弱相关；正式报告需同时展示平均连通性及 scale-free 检验，并说明 β 是自动推荐还是用户指定。','This example uses a signed network with <strong>β = 8</strong>, the first illustrative candidate to reach R² ≥ 0.85. Power strengthens the contrast between stronger and weaker correlations. The production report also includes mean connectivity and scale-free diagnostic plots, and states whether power was recommended or manually chosen.'))
 out+=fig('soft-threshold','03_soft_threshold',2,L('软阈值候选与拟合指标（模拟曲线）。','Candidate powers and fit index (synthetic curve).'),L('怎么看：横轴是候选 β，纵轴是拟合指标。虚线是本次目标线，棕色点是采用值。达到目标线只是选参依据之一，不能单独证明网络可靠。','How to read: candidate power is on the x-axis, fit index on the y-axis. The dashed line is the target; the brown point is the chosen power. Reaching the target alone does not establish network reliability.'))+'</section>'
 out+=step(5,L('将表达模式相似的基因分组，并记录未分配基因。','Group genes with similar expression patterns and record unassigned genes.'))
 out+=story(L('本例根据 signed 网络的拓扑重叠关系聚类，再识别基因模块。最小模块大小设为 30，模块合并距离阈值为 0.25。示例最终有 <strong>4 个模块</strong>，另有 <strong>200 个 grey 基因</strong>未分配到模块；grey 不计入模块总数。','Genes are clustered using topological overlap in a signed network. Minimum module size is 30; the module-merging distance threshold is 0.25. The example contains <strong>4 modules</strong> and <strong>200 unassigned grey genes</strong>; grey is excluded from the module count.'))
 out+=fig('modules','04_network',3,L('基因聚类与模块色带（示意图）。','Gene clustering and module assignments (illustration).'),L('怎么看：下方同色区域表示同一模块，模块色仅作名称标识。正式报告保留 app 中展示的合并前 / 合并后色带及其原始标签，不重新命名。','How to read: genes with the same assignment color belong to one module. Colors act as module names. Production export preserves the app pre/post-merge rows and their labels.'))
 out+=table(L(['模块','基因数','占建网基因比例'],['Module','Gene count','Share of network input']),[[f'<span style="color:{co}">●</span> {m}',f'{n:,}',f'{n/80:.2f}%'] for co,m,n in zip(colors+['#a1a6a3'],mods+['grey'],[2700,2200,1800,1100,200])])+'</section>'
 out+=step(6,L('用模块特征向量概括模块表达，再与所选性状比较。','Summarize module expression using its eigengene, then compare it with selected traits.'))
 out+=story(L('模块特征向量（ME）是模块表达的主要变化模式，并不是某一个“代表基因”。热图展示 ME 与性状的相关系数；正式结果还需显示 p 值，并标明检验方法和是否校正多重比较。','A module eigengene (ME) summarizes the main pattern of module expression; it is not a single representative gene. The heatmap shows ME–trait correlation. Actual results must also display p-values, the statistical test and whether multiple comparisons were adjusted.'))
 out+=fig('module-trait','05_module_trait',4,L('模块–性状相关热图；仅示范布局与色阶。','Module–trait heatmap; illustrative layout and color scale.'),L('怎么看：红色偏正相关，蓝色偏负相关，颜色越深表示绝对相关越强。相关性不代表因果关系。这个示意图没有真实 p 值，也不作显著性结论。','How to read: red indicates positive correlation and blue negative correlation; deeper colors indicate larger absolute correlations. Correlation does not imply causation. This illustration has no actual p-values and makes no significance claims.'))+'</section>'
 out+=step(7,L('围绕用户选定的模块与性状，整理基因表现与功能线索。','Inspect gene-level patterns and functional context for the selected module and trait.'))
 out+=f'<div class="download-row"><span class="pill">{L("所选模块","Selected module")}: turquoise</span><span class="pill">{L("所选性状","Selected trait")}: Drought</span></div>'
 out+=fig('gs-mm','06_module_detail/turquoise',5,L('GS 与模块隶属度散点（模拟点）。','GS versus module membership (synthetic points).'),L('怎么看：每个点是一个基因。|kME| 越大，表达模式与模块越一致；|GS| 越大，与目标性状的关联越强。虚线示范候选筛选边界，正式图使用当前 app 的相关方向、阈值与坐标设置。','How to read: each point is a gene. Larger |kME| indicates stronger alignment with the module; larger |GS| indicates stronger association with the trait. Dashed lines illustrate selection boundaries. Actual figures follow the app correlation direction, thresholds and axes.'))
 out+=fig('enrichment','06_module_detail/turquoise',6,L('GO 富集气泡图（模拟术语与数值）。','GO enrichment dot plot (synthetic terms and values).'),L('怎么看：每一行是一个功能条目，点的位置表示入选基因比例。正式图的点大小、色阶、校正后 p 值及 GO / KEGG 背景均按 app 当前设置导出；此示意图不作富集结论。未提供背景、未运行或无显著条目时，报告应明确标明对应状态。','How to read: each row is a functional term; horizontal position indicates the selected-gene ratio. Actual dot size, color scale, adjusted p-values and GO/KEGG backgrounds follow app settings. This illustration makes no enrichment claims. Missing backgrounds, unrun analyses and no significant terms must be reported as distinct states.'))+'</section>'
 out+=step(8,L('把“候选筛选”与“网络展示”分开记录，避免将展示数量误作全部候选数量。','Distinguish candidate selection from the displayed network size.'))
 out+=story(L('本例在 turquoise 模块、Drought 性状下，用 <strong>|kME| ≥ 0.8、|GS| ≥ 0.5</strong>作为筛选条件，示例有 42 个候选。网络最多展示 30 个 Hub，每个最多保留 20 个邻居，边权重下限为 0.02。正式报告以引擎实际采用的比较符号、排序和截断规则为准，并导出全部候选与最终展示的节点 / 边。','For turquoise and Drought, this example selects candidates using <strong>|kME| ≥ 0.8 and |GS| ≥ 0.5</strong>, yielding 42 illustrative candidates. The network displays at most 30 hubs, up to 20 neighbors per hub and edges with weight at least 0.02. Production reports must reflect the engine comparison operators, ranking and limits, and export all candidates as well as displayed nodes and edges.'))
 out+=fig('network','07_hub/turquoise/Drought',7,L('网络排版示意；不代表本模块真实连接。','Network layout illustration; not actual module connections.'),L('怎么看：节点表示基因，连线表示通过阈值的共表达关系。此图仅供审阅视觉风格；正式报告使用 app 的当前网络节点、边、位置、标签、大小及颜色，避免导出时随机重排。','How to read: nodes represent genes; edges represent co-expression links passing the threshold. This figure demonstrates visual style only. Production export uses the current app nodes, edges, positions, labels, sizes and colors to prevent random rearrangement.'))+'</section>'
 out+=step(9,L('让阅读报告的人能回到原始图表、数据和分析设定。','Keep figures, data and analysis settings within reach.'))
 out+=table(L(['内容','路径','说明'],['Contents','Path','Purpose']),[['HTML','report/index.html',L('本语言的报告入口','Report entry in the chosen language')],['Quarto','report/report.qmd',L('可重新编译的报告源文件','Editable, re-renderable report source')],[L('全部图表与表格','Figures & tables'),'result/01_input/ … 07_hub/',L('按报告步骤编号归档','Organized by report step')],[L('读图说明','Reading guide'),'result/README.txt',L('文件索引、字段和读图方法','File index, columns and interpretation')],[L('分析记录','Analysis provenance'),'result/00_provenance/',L('最终参数、视图快照、环境和文件校验','Final parameters, view state, environment and checksums')]])
 out+=f'<div class="download-row"><a class="button" href="../result/README.txt" download>{L("下载读图说明","Download reading guide")}</a><a href="../result/00_provenance/view-state.json" download>{L("查看视图快照示例","Example view snapshot")}</a><a href="report.qmd" download>{L("下载 Quarto 源文件","Download Quarto source")}</a></div>'
